'use strict';
(() => {
    const platform = location.pathname === '/platform';
    if (platform) document.body.classList.add('platform-mode');;
    const names = {ACTIVE:'Activo',SUSPENDED:'Suspendido',CLOSED:'Dado de baja',PAID:'Pagado',PARTIAL:'Pago parcial',OPEN:'Pendiente',OVERDUE:'Vencido',VOID:'Anulado',INFO:'Información',WARNING:'Advertencia',URGENT:'Urgente',TRANSFER:'Transferencia',CASH:'Efectivo',CARD:'Tarjeta',OTHER:'Otro'};
    const money = (n,c='USD') => new Intl.NumberFormat('es',{style:'currency',currency:c}).format(Number(n || 0)/100);
    const badge = s => `<span class="commercial-badge ${esc(s)}">${esc(names[s] || s)}</span>`;
    const date = s => s ? esc(s.slice(0,10)) : '—';
    const amount = (name,label,value='') => field(name,label,'number',value,'required min="0" max="10000000" step="any" data-money');;
    const select = (name,label,items,value) => `<label for="${name}">${label}</label><select id="${name}" name="${name}">${items.map(([v,n])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`).join('')}</select>`;
    const minor = v => { if(!/^\d+(\.\d{1,2})?$/.test(v))throw new Error('Usa un monto con hasta dos decimales.'); return Math.round(Number(v)*100); };
    const stat = (label,value,note='') => `<div class="commercial-stat"><span>${esc(label)}</span><strong>${esc(value)}</strong>${note?`<small>${esc(note)}</small>`:''}</div>`;
    const table = (heads,rows,empty='Todavía no hay registros.') => rows.length ? `<div class="commercial-table-wrap"><table class="commercial-table"><thead><tr>${heads.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>{let col=0;return row.replace(/<td(?=[ >])/g,()=>`<td data-label="${esc(heads[col++]||'')}"`)}).join('')}</tbody></table></div>` : `<p class="commercial-empty">${esc(empty)}</p>`;
    let selected = null, accountData = null, pane = 'account', offset = 0, requestVersion = 0;
    const endpoint = () => platform ? `/api/platform/tenants/${selected}` : '/api/staff';
    const handle = fn => async () => {try{await fn()}catch(e){notice(e.message)}};
    function dialog(title,fields,handler,label='Guardar',warning='') {
        document.querySelector('#commercialDialog')?.remove();
        const d = document.createElement('dialog'); d.id='commercialDialog';d.className='commercial-dialog';
        d.innerHTML=`<h2>${esc(title)}</h2>${warning?`<p>${esc(warning)}</p>`:''}<form id="commercialForm">${fields}<div class="row"><button type="button" class="quiet" id="closeDialog">Cancelar</button><button type="submit">${esc(label)}</button></div></form>`;
        document.body.append(d); d.showModal();
                action('closeDialog',()=>d.close());d.addEventListener('close',()=>d.remove());
        form('commercialForm',async(values,f)=>{await handler(values,f);d.close()});
        const businessName=d.querySelector('[name=name]'),businessSlug=d.querySelector('[name=slug]');
        if(businessName&&businessSlug){let edited=false;businessSlug.addEventListener('input',()=>{edited=true});businessName.addEventListener('input',()=>{if(!edited)businessSlug.value=businessName.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)});}

    }
    const profilePayload = v => ({legalName: v.legalName.trim(), ruc: v.ruc.trim(), activity: v.activity.trim(), contactName: v.contactName.trim(), email: v.email.trim(), phone: v.phone.trim(), province: v.province.trim(), city: v.city.trim(), address: v.address.trim(), website: (v.website || '').trim(), socialLinks: Object.fromEntries(['instagram','facebook','tiktok','youtube','whatsapp'].map(k=>[k,(v[k]||'').trim()]).filter(([,v])=>v))});
    function profileFields(p = {}, part = 'all') {
        const identity = `<div class="business-field-grid"><div>${field('legalName', 'Razón social', 'text', p.legalName || '', 'required maxlength="200" autocomplete="organization"')}<small>Como aparece en el registro tributario.</small></div><div>${field('ruc', 'RUC de Ecuador', 'text', p.ruc || '', 'required inputmode="numeric" pattern="[0-9]{13}" minlength="13" maxlength="13" aria-describedby="rucHelp"')}<small id="rucHelp">13 dígitos. El estado tributario no se verifica automáticamente.</small></div><div class="full-width">${field('activity', 'Actividad del negocio', 'text', p.activity || '', 'required maxlength="100" placeholder="Ej.: cafetería, barbería, moda, servicios…"')}</div></div>`;
        const contact = `<div class="business-field-grid"><div>${field('contactName', 'Persona de contacto', 'text', p.contactName || '', 'required maxlength="120" autocomplete="name"')}</div><div>${field('phone', 'Teléfono de contacto', 'tel', p.phone || '', 'required maxlength="30" autocomplete="tel" placeholder="+593 99 123 4567"')}</div><div class="full-width">${field('email', 'Correo del negocio', 'email', p.email || '', 'required maxlength="254" autocomplete="email" placeholder="contacto@negocio.com"')}</div><div>${field('province', 'Provincia', 'text', p.province || '', 'required maxlength="80" autocomplete="address-level1"')}</div><div>${field('city', 'Ciudad', 'text', p.city || '', 'required maxlength="80" autocomplete="address-level2"')}</div><div class="full-width">${field('address', 'Dirección del negocio', 'text', p.address || '', 'required maxlength="250" autocomplete="street-address" placeholder="Calle principal, número y referencia"')}</div><div class="full-width">${field('website', 'Página web (opcional)', 'url', p.website || '', 'maxlength="250" placeholder="https://negocio.com"')}</div></div>`;
        const social = `<details class="social-fields" ${part === 'all' ? 'open' : ''}><summary>Redes sociales (opcionales)</summary><p class="small">Pega el enlace completo de cada perfil. Puedes actualizarlos cuando lo necesites.</p>${[['instagram','Instagram'],['facebook','Facebook'],['tiktok','TikTok'],['youtube','YouTube'],['whatsapp','WhatsApp']].map(([key,label])=>field(key,label,'url',p.socialLinks?.[key]||'','maxlength="250" placeholder="https://…"')).join('')}</details>`;
        return part === 'identity' ? identity : part === 'contact' ? contact + social : `<h3>Identidad del negocio</h3>${identity}<h3 class="profile-section-title">Contacto y ubicación</h3>${contact}${social}`;
    }
    function openBusinessRegistration() {
        document.querySelector('#commercialDialog')?.remove();
        const d = document.createElement('dialog'); d.id = 'commercialDialog'; d.className = 'commercial-dialog business-registration';
        d.innerHTML = `<div class="registration-heading"><div><span class="eyebrow">Nuevo negocio</span><h2>Todo listo desde el primer día.</h2></div><button type="button" class="quiet" id="closeRegistration" aria-label="Cerrar registro">Cerrar</button></div><ol class="registration-steps" aria-label="Pasos del registro"><li data-registration-step="0">1 <span>Negocio</span></li><li data-registration-step="1">2 <span>Contacto</span></li><li data-registration-step="2">3 <span>Revisión</span></li></ol><form id="businessRegistration" novalidate><fieldset data-registration-panel="0"><legend>¿Cómo se llama el negocio?</legend>${field('name', 'Nombre comercial', 'text', '', 'required maxlength="120" placeholder="El nombre que reconocerán tus clientes"')}${profileFields({}, 'identity')}</fieldset><fieldset data-registration-panel="1" hidden><legend>¿Cómo podemos contactar al negocio?</legend>${profileFields({}, 'contact')}</fieldset><fieldset data-registration-panel="2" hidden><legend>Primera sucursal y revisión</legend><div class="business-field-grid"><div>${field('firstBranchName', 'Nombre de la primera sucursal', 'text', 'Principal', 'required maxlength="120"')}</div><div>${field('firstBranchCode', 'Código interno', 'text', 'PRINCIPAL', 'required maxlength="40"')}</div></div><div class="registration-summary" id="registrationSummary"></div><p class="small">La tarjeta del negocio funcionará en todas sus sucursales. Podrás añadir más locales después.</p><details><summary>Enlace, moneda y zona horaria</summary>${field('slug', 'Enlace del registro de clientes', 'text', '', 'required pattern="[a-z0-9][a-z0-9-]{2,59}" minlength="3" maxlength="60"')}<p class="small">Se genera a partir del nombre comercial. Usa letras sin tildes, números y guiones.</p>${select('currency', 'Moneda', [['USD','USD · Dólar'],['EUR','EUR · Euro'],['COP','COP · Peso colombiano'],['PEN','PEN · Sol'],['MXN','MXN · Peso mexicano']], 'USD')}${field('timezone', 'Zona horaria', 'text', 'America/Guayaquil', 'required')}</details></fieldset><div class="registration-actions"><button type="button" class="quiet" id="registrationBack" hidden>Volver</button><button type="submit" id="registrationNext">Continuar →</button></div></form>`;
        document.body.append(d); d.showModal();
        const f=d.querySelector('form'); let step=0, slugEdited=false;
        const busy=()=>f.getAttribute('aria-busy')==='true';
        d.querySelector('#closeRegistration').onclick=()=>{if(!busy())d.close();}; d.addEventListener('cancel',e=>{if(busy())e.preventDefault();}); d.addEventListener('close',()=>d.remove());
        f.elements.slug.addEventListener('input',()=>{slugEdited=true;});
        f.elements.name.addEventListener('input',()=>{if(!slugEdited)f.elements.slug.value=f.elements.name.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60);});
        const show=()=>{
            d.querySelectorAll('[data-registration-panel]').forEach(p=>p.hidden=Number(p.dataset.registrationPanel)!==step);
            d.querySelectorAll('[data-registration-step]').forEach(p=>{const current=Number(p.dataset.registrationStep)===step;p.classList.toggle('current',current);if(current)p.setAttribute('aria-current','step');else p.removeAttribute('aria-current');});
            d.querySelector('#registrationBack').hidden=step===0;d.querySelector('#registrationNext').textContent=step===2?'Crear negocio':'Continuar →';
            if(step===2){const v=Object.fromEntries(new FormData(f));d.querySelector('#registrationSummary').innerHTML=`<strong>${esc(v.name)}</strong><p>${esc(v.legalName)} · RUC ${esc(v.ruc)}</p><p>${esc(v.contactName)} · ${esc(v.email)}<br>${esc(v.phone)} · ${esc(v.city)}, ${esc(v.province)}</p><p>${esc(v.address)}</p>`;}
            d.querySelector(`[data-registration-panel="${step}"] input`)?.focus();d.scrollTop=0;
        };
        const validate=all=>{
            const fields=[...d.querySelectorAll(all?'fieldset input,fieldset select':`[data-registration-panel="${step}"] input,[data-registration-panel="${step}"] select`)];
            for(const input of fields){input.setCustomValidity(input.required&&!input.value.trim()?'Completa este dato para continuar.':'');if(!input.checkValidity()){step=Number(input.closest('[data-registration-panel]').dataset.registrationPanel);show();const details=input.closest('details');if(details)details.open=true;input.reportValidity();return false;}}
            return true;
        };
        f.addEventListener('submit',e=>{if(busy()){e.preventDefault();e.stopImmediatePropagation();return;}if(!validate(step===2)){e.preventDefault();e.stopImmediatePropagation();return;}if(step<2){e.preventDefault();e.stopImmediatePropagation();step++;show();}},true);
        f.addEventListener('input',e=>{if(e.target.setCustomValidity)e.target.setCustomValidity('');});
        d.querySelector('#registrationBack').onclick=()=>{if(!busy()){step--;show();}};
        form('businessRegistration',async(v)=>{
            const session=state.token;
            const result=await api('/api/platform/businesses',{name:v.name.trim(),slug:v.slug,currency:v.currency,timezone:v.timezone,firstBranch:{name:v.firstBranchName.trim(),code:v.firstBranchCode.trim()},profile:profilePayload(v)});
            if(session!==state.token||!d.isConnected)return;
            d.close();await listBusinesses().catch(()=>{if(session===state.token)app.innerHTML='<section class="panel"><h2>Negocio creado</h2><p>Vuelve a abrir la lista para consultar sus datos.</p></section>';});
            if(session!==state.token)return;
            const panel=document.createElement('section');panel.className='panel business-created';panel.innerHTML=`<span class="eyebrow">Registro completado</span><h2>${esc(v.name)} ya está creado.</h2><p>Guarda esta credencial y entrégala al dueño por un medio privado. Solo se muestra ahora.</p><div class="code">${esc(result.ownerToken)}</div><p>Registro de clientes: <a href="${esc(result.enrollmentPath)}">${esc(result.enrollmentPath)}</a></p><button type="button" id="openCreatedBusiness">Ver datos del negocio</button>`;app.prepend(panel);
            panel.querySelector('#openCreatedBusiness').onclick=handle(async()=>{selected=result.tenantId;pane='profile';offset=0;await loadAccount();});notice('Negocio y primera sucursal creados.');
        });show();
    }
    async function renderBusinessProfile(root) {
        const path=platform?`/api/platform/tenants/${selected}/profile`:'/api/staff/business-profile';
        const session=state.token, tab=state.tab, currentPane=pane, tenant=selected, request=String(++requestVersion);
        root.dataset.profileRequest=request; root.innerHTML='<section class="panel" role="status">Cargando datos del negocio…</section>';
        const valid=()=>root.isConnected&&state.tab===tab&&pane===currentPane&&session===state.token&&root.dataset.profileRequest===request&&(!platform||tenant===selected);
        let data;
        try { data=await api(path); } catch(issue) {
            if(!valid())return;
            root.innerHTML=`<section class="panel"><h2>No pudimos cargar la ficha</h2><p role="alert">${esc(issue.message)}</p><button type="button" id="reloadBusinessProfile">Volver a intentar</button></section>`;
            root.querySelector('#reloadBusinessProfile').onclick=()=>renderBusinessProfile(root);return;
        }
        if(!valid())return;let version=data.version, savedProfile=data.profile;
        const protectedFields=['legalName','ruc','activity','province','city','address'];
        const requests=data.requests||[], pending=requests.find(r=>r.status==='PENDING');
        root.innerHTML=`<section class="panel business-profile"><div class="commercial-heading-row"><div><span class="eyebrow">Datos del negocio</span><h2>${esc(data.business.name)}</h2><p>${platform?'Revisa la información del negocio y documenta las correcciones.':'Actualiza tu contacto y tus redes. Tu identidad y ubicación se mantienen protegidas.'}</p></div><span class="profile-status">${data.profile?'Ficha completa':'Requiere completar datos'}</span></div>
            <div class="profile-lock"><strong>${platform?'Cambios con verificación':'Datos protegidos por la administración'}</strong><p>${platform?'Para cambiar razón social, RUC, actividad o ubicación, verifica la solicitud y registra el motivo.':'La razón social, el RUC, la actividad y la ubicación solo pueden ser corregidos por el administrador.'}</p>${!platform?'<button type="button" class="quiet" id="jumpToProfileRequest">Solicitar una corrección ↓</button>':''}</div>
            ${data.profile||platform?`<form id="businessProfileForm">${profileFields(data.profile||{})}${platform?`<div id="correctionReasonWrap" hidden>${field('correctionReason','Qué verificaste y por qué realizas el cambio','text','','minlength="10" maxlength="500" placeholder="Referencia de la solicitud y verificación realizada"')}</div>`:''}<p class="small">La ficha es privada para el dueño y el administrador. Registrar un RUC no certifica su situación tributaria.</p><button type="submit">${platform?'Guardar datos verificados':'Guardar contacto y redes'}</button><p id="profileSaved" role="status"></p></form>`:'<p>El administrador debe completar la ficha inicial. Envía abajo los datos que necesita revisar. Tus tarjetas y operaciones siguen disponibles.</p>'}</section>
            <section class="panel profile-requests" id="profileRequests"><h2>${platform?'Solicitudes de corrección':'Comunícate con el administrador'}</h2><p>Esta solicitud queda en el panel de administración; no modifica los datos ni envía un correo.</p>${!platform&&!pending?'<form id="profileRequestForm"><label for="profileRequestDetails">Qué dato necesitas corregir</label><textarea id="profileRequestDetails" name="details" rows="4" required minlength="10" maxlength="1000" placeholder="Indica el dato actual, el dato correcto y el motivo. No incluyas contraseñas."></textarea><button>Enviar solicitud de corrección</button></form>':''}${pending&&!platform?'<p class="profile-status" role="status">Tienes una solicitud pendiente de revisión.</p>':''}<div class="request-list">${requests.map(r=>`<article class="request-card"><div class="commercial-heading-row"><strong>${({PENDING:'Pendiente',RESOLVED:'Atendida',REJECTED:'No aprobada'})[r.status]||esc(r.status)}</strong><span class="small">${date(r.createdAt)}</span></div><p class="request-text">${esc(r.details)}</p>${r.response?`<p><strong>Respuesta del administrador:</strong> ${esc(r.response)}</p>`:''}${platform&&r.status==='PENDING'?`<form id="resolveProfileRequest" data-request-id="${esc(r.id)}">${select('resolution','Resultado de la revisión',[['RESOLVED','Atendida · datos verificados'],['REJECTED','No aprobada · explicar el motivo']],'RESOLVED')}<label for="resolutionResponse">Respuesta para el dueño</label><textarea name="response" id="resolutionResponse" required minlength="10" maxlength="1000" rows="3"></textarea><label class="check"><input name="reviewed" type="checkbox" required>Revisé la solicitud. Si requiere correcciones, ya guardé los datos verificados arriba.</label><button>Guardar respuesta y cerrar solicitud</button></form>`:''}</article>`).join('')||'<p>Aún no hay solicitudes.</p>'}</div><p class="small">Se muestran las diez solicitudes más recientes.</p></section>`;
        const f=root.querySelector('#businessProfileForm');
        if(f){
            if(!platform)protectedFields.forEach(name=>{f.elements[name].readOnly=true;f.elements[name].setAttribute('aria-description','Solo el administrador puede corregir este dato.');});
            const syncReason=()=>{if(!platform)return;const changed=!savedProfile||protectedFields.some(k=>f.elements[k].value.trim()!==savedProfile[k].trim());root.querySelector('#correctionReasonWrap').hidden=!changed;f.elements.correctionReason.required=changed;};
            f.addEventListener('input',syncReason);syncReason();
            form('businessProfileForm',async(v)=>{
                let result;
                try{result=await api(path,{expectedVersion:version,profile:profilePayload(v),reason:v.correctionReason||''},'PUT');}
                catch(issue){
                    if(issue.code==='PROFILE_CHANGED'&&valid()&&!root.querySelector('.profile-conflict')){
                        const recovery=document.createElement('div');recovery.className='profile-conflict';recovery.innerHTML='<p>Otra persona guardó cambios. Tu edición sigue aquí. Recarga para revisar la ficha vigente antes de volver a guardar.</p><button type="button" class="quiet">Recargar ficha guardada</button>';
                        recovery.querySelector('button').onclick=()=>{if(!root.querySelector('form[aria-busy="true"]'))renderBusinessProfile(root);};root.querySelector('.business-profile').append(recovery);
                    }throw issue;
                }
                if(!valid())return;version=result.version;savedProfile=result.profile;root.querySelector('.profile-conflict')?.remove();root.querySelector('.profile-status').textContent='Ficha completa';root.querySelector('#profileSaved').textContent='Datos guardados.';syncReason();if(platform)f.elements.correctionReason.value='';
            });
        }
        root.querySelector('#jumpToProfileRequest')?.addEventListener('click',()=>{root.querySelector('#profileRequests').scrollIntoView({behavior:'smooth'});root.querySelector('#profileRequestDetails')?.focus({preventScroll:true});});
        form('profileRequestForm',async(v,f)=>{const payload={details:v.details.trim()};await api('/api/staff/business-profile/requests',payload,'POST',operationKey(f,payload));if(valid())await renderBusinessProfile(root);});
        form('resolveProfileRequest',async(v,f)=>{if(v.reviewed!=='on')throw new Error('Confirma que revisaste la solicitud.');await api(`/api/platform/tenants/${tenant}/profile-requests/${f.dataset.requestId}`,{status:v.resolution,response:v.response.trim()},'PUT');if(valid())await renderBusinessProfile(root);});
    }
    function login() {

        exit.hidden=true;
        app.innerHTML=`<section class="narrow"><div class="eyebrow">Administración de plataforma</div><h1>Cada negocio,<br>bien acompañado.</h1><p>Administra membresías, pagos y permanencia. Consulta cómo crece tu comunidad.</p><section class="panel"><h2>Entrar a la plataforma</h2><form id="platformLogin">${field('platformToken','Credencial de plataforma','password','','required autocomplete="off"')}<button type="submit">Entrar</button></form><p class="commercial-note">Usa tu credencial de administración. Si administras una tienda, entra desde el acceso de negocios.</p></section><a href="/">Ir al acceso de negocios</a></section>`;
        form('platformLogin',async v=>{state.token=v.platformToken.trim();try{await listBusinesses()}catch(e){state.token='';throw e}});
    }
    async function listBusinesses(query='',page=0) {
        const ticket=++requestVersion;
        const data=await api(`/api/platform/tenants?q=${encodeURIComponent(query)}&offset=${page}`);
                if(ticket!==requestVersion)return;
        exit.hidden=false;selected=null;
        app.innerHTML=`<div class="commercial-head"><div><div class="eyebrow">Tu plataforma</div><h1>Tus negocios, en orden.</h1><p>Busca un negocio, revisa su cuenta o registra uno nuevo.</p></div><div class="row"><button id="newBusiness">Añadir negocio</button><button class="quiet" id="addExistingLocation">Añadir local a un negocio</button></div></div><div class="commercial-stats">${stat('En esta página',data.items.length)}${stat('Activos',data.items.filter(x=>x.state==='ACTIVE').length)}${stat('Suspendidos',data.items.filter(x=>x.state==='SUSPENDED').length)}${stat('Clientes de esta página',data.items.reduce((a,b)=>a+b.clients,0))}</div><section class="panel"><form id="businessSearch" class="commercial-search"><div>${field('query','Buscar negocio por nombre o RUC','search',query,'maxlength="100" placeholder="Escribe para ver sugerencias…"')}</div><button type="submit">Buscar</button></form>${table(['Negocio','Estado','Clientes','Saldo emitido','Próximo cargo',''],data.items.map(b=>`<tr><td class="commercial-identity">${esc(b.name)}<small>${b.ruc ? 'RUC ' + esc(b.ruc) : 'Ficha por completar'}${b.city ? ' · ' + esc(b.city) : ''}</small>${b.pendingProfileRequests?'<span class="request-badge">Solicitud de corrección pendiente</span>':''}</td><td>${badge(b.state)}</td><td>${b.clients}</td><td>${money(b.balanceMinor,b.currency)}</td><td>${date(b.nextChargeOn)}</td><td><button class="quiet" data-business="${esc(b.id)}">Administrar</button></td></tr>`),'Añade tu primer negocio para empezar.')}<div class="commercial-pager"><button class="quiet" id="listPrev" ${page===0?'disabled':''}>Anterior</button><span>Página ${Math.floor(page/50)+1}</span><button class="quiet" id="listNext" ${data.nextOffset===null?'disabled':''}>Siguiente</button></div><p class="commercial-note">Los saldos corresponden a cargos emitidos. Los cargos programados se actualizan en segundo plano y al abrir cada cuenta. Cada negocio conserva su propia moneda.</p></section>`;
        attachPredictiveSearch(document.querySelector('#query'),{
            load:async q=>(await api('/api/platform/tenant-suggestions?q='+encodeURIComponent(q))).items,
            label:row=>row.name,description:row=>[row.ruc?'RUC '+row.ruc:'Ficha por completar',row.city].filter(Boolean).join(' · '),
            choose:async row=>{selected=row.id;pane='account';offset=0;await loadAccount();}
        });
        form('businessSearch',v=>listBusinesses(v.query,0));action('listPrev',()=>listBusinesses(query,Math.max(0,page-50)));action('listNext',()=>listBusinesses(query,data.nextOffset));
        document.querySelectorAll('[data-business]').forEach(b=>b.onclick=handle(async()=>{selected=b.dataset.business;pane='account';offset=0;await loadAccount()}));
        action('newBusiness',openBusinessRegistration);
        action('addExistingLocation',()=>{
            if(!data.items.length){notice('Busca primero el negocio al que pertenece este local.');return;}
            dialog('Relacionar un nuevo local',`${select('tenantId','Negocio que comparte la tarjeta',data.items.map(b=>[b.id,b.name]))}${field('name','Nombre del nuevo local','text','','required maxlength="120"')}${field('code','Código del local','text','','required maxlength="40"')}<p>El local se añade como sucursal del negocio seleccionado. Los clientes conservan su tarjeta y saldo. La lista corresponde a tu búsqueda actual.</p>`,async(v,f)=>{
                const payload={name:v.name,code:v.code};await api(`/api/platform/tenants/${encodeURIComponent(v.tenantId)}/branches`,payload,'POST',operationKey(f,payload));
                selected=v.tenantId;pane='branches';await loadAccount();notice('Local añadido al mismo negocio.');
            },'Añadir local');
        });
    }
    async function renderLocations(root) {
        const tenant=selected;
        const data=await api(`${endpoint()}/branches`);
        if(tenant!==selected || !root.isConnected)return;
        root.innerHTML=`<section class="panel"><h2>Una tarjeta para todos los locales</h2><p>Las sucursales de ${esc(data.business.name)} comparten clientes, saldo y premios. Las promociones configuradas para todas las sucursales también incluyen los locales nuevos.</p>${table(['Sucursal','Código'],data.branches.map(b=>`<tr><td>${esc(b.name)}</td><td>${esc(b.code)}</td></tr>`),'Añade una sucursal para comenzar.')}<form id="platformBranch">${field('name','Nombre del local','text','','required maxlength="120"')}${field('code','Código único dentro del negocio','text','','required maxlength="40"')}<button>Añadir sucursal</button></form></section><section class="panel"><h2>Dar acceso al negocio</h2><p>El dueño administra promociones y premios. El cajero registra compras y canjes en su sucursal.</p><form id="platformStaff">${select('role','Tipo de acceso',[['CASHIER','Cajero'],['OWNER','Dueño del negocio']],'CASHIER')}${select('branchId','Sucursal del cajero',data.branches.map(b=>[b.id,b.name]))}<button>Crear credencial privada</button></form><div id="platformIssued"></div></section>`;
        form('platformBranch',async(v,f)=>{const payload={name:v.name,code:v.code};await api(`/api/platform/tenants/${tenant}/branches`,payload,'POST',operationKey(f,payload));await renderLocations(root);notice('Sucursal añadida. Comparte la tarjeta del negocio.');});
        const role=root.querySelector('[name=role]'),branch=root.querySelector('[name=branchId]');
        const change=()=>{branch.disabled=role.value==='OWNER';branch.required=role.value==='CASHIER';};role.onchange=change;change();
        form('platformStaff',async v=>{
            const result=await api(`/api/platform/tenants/${tenant}/credentials`,{role:v.role,branchId:v.role==='CASHIER'?v.branchId:null});
            if(tenant!==selected || !root.isConnected)return;
            root.querySelector('#platformIssued').innerHTML=`<h3>Guarda esta credencial</h3><p>Se muestra una vez. Entrégala al responsable por un medio privado.</p><div class="code">${esc(result.token)}</div><p>El responsable entra desde el acceso de negocios. Los clientes siguen sin contraseña.</p>`;
        });
    }
    async function loadAccount() {

        const ticket=++requestVersion;const result=await api(`${endpoint()}/account?offset=${offset}`);
        if(ticket!==requestVersion)return;accountData=result;renderAccount();
    }
    function shell() {
        const d=accountData,b=d.business;
        if(platform){
            app.innerHTML=`<div class="commercial-head"><div><button class="quiet" id="backBusinesses">← Negocios</button><h1>${esc(b.name)}</h1><p>En la plataforma desde ${date(b.joinedAt)} · ${b.tenureDays} días · ${esc(b.currency)}</p></div>${badge(d.access.effectiveState)}</div><div id="commercialRoot" class="commercial-account"></div>`;
            action('backBusinesses',()=>listBusinesses());
                }
        const root=document.querySelector(platform?'#commercialRoot':'#content');if(!root)return null;
        root.innerHTML=`<nav aria-label="Administración de cuenta">${[['account','Estado de cuenta'],['profile','Datos del negocio'],...(platform?[['branches','Sucursales y accesos'],['membership','Membresía'],['access','Estado del negocio']]:[]),['notices','Avisos'],['metrics','Informes']].map(([key,label])=>`<button data-commercial-pane="${key}" class="${pane===key?'active':''}">${label}</button>`).join('')}</nav><div id="commercialPane"></div>`;
        root.querySelectorAll('[data-commercial-pane]').forEach(b=>b.onclick=handle(async()=>{pane=b.dataset.commercialPane;renderAccount()}));
        return document.querySelector('#commercialPane');
;
    }
        function renderAccount() {
        const root=shell();if(!root)return;
        if(pane==='account'){renderStatement(root);}
        else if(pane==='profile'){renderBusinessProfile(root).catch(e=>notice(e.message));}
        else if(pane==='branches'){renderLocations(root).catch(e=>notice(e.message));}
        else if(pane==='membership'){renderMembership(root);}
        else if(pane==='access'){renderAccess(root);}
        else if(pane==='notices'){renderNotices(root);}
        else if(pane==='metrics'){renderMetrics(root).catch(e=>notice(e.message));}
    }
    function warnings(d) {
        const a=d.access,s=d.summary,m=d.membership;
        return `${a.effectiveState!=='ACTIVE'?`<div class="commercial-alert"><strong>${a.effectiveState==='CLOSED'?'Negocio dado de baja':'Operaciones suspendidas'}</strong><p>${a.overdueSuspension?'Hay cargos pendientes fuera del plazo de gracia. Al saldarlos, el acceso se recupera automáticamente.':esc(a.reason)}</p><p>Los clientes y sus saldos se conservan. Puedes seguir consultando esta cuenta.</p></div>`:''}${s.overdueMinor>0?`<div class="commercial-alert">Saldo vencido: <strong>${money(s.overdueMinor,d.business.currency)}</strong>. Revisa los cargos pendientes.</div>`:''}${s.nextDueOn && s.nextDueOn>=d.today && s.nextDueOn<=new Date(Date.parse(d.today+'T12:00:00Z')+7*864e5).toISOString().slice(0,10)?`<div class="commercial-alert info">Tienes un vencimiento próximo: <strong>${date(s.nextDueOn)}</strong>.</div>`:''}${!m?'<p class="commercial-note">Todavía no se ha configurado una membresía. No se generan cargos recurrentes.</p>':''}`;
    }
    function renderStatement(root) {
        const d=accountData,c=d.business.currency,m=d.membership;
        root.innerHTML=`${warnings(d)}<div class="commercial-stats">${stat('Saldo pendiente',money(d.summary.balanceMinor,c))}${stat('Saldo vencido',money(d.summary.overdueMinor,c))}${stat('Próximo vencimiento',d.summary.nextDueOn||'Sin cargos')}${stat('Próximo cargo',m?.plan.recurring?m.nextChargeOn:'Sin programación')}</div><section class="panel"><div class="commercial-heading-row"><h2>Cargos y vencimientos</h2>${platform?'<button id="addCharge">Añadir cargo</button>':''}</div>${m?`<p>${esc(m.plan.name)} · ${money(m.plan.feeMinor,c)} cada ${m.plan.intervalMonths} mes(es) · Alta de membresía: ${date(m.plan.startedOn)} · ${m.plan.recurring?'Programación activa':'Programación pausada'}</p>`:''}${table(['Concepto','Vencimiento','Importe','Pendiente','Estado',...(platform?['Acciones']:[])],d.invoices.map(i=>`<tr><td>${esc(i.description)}${i.periodStart?`<small>${date(i.periodStart)} → ${date(i.periodEnd)} · v${i.planVersion}</small>`:''}<small>${esc(i.id)}</small>${i.voidReason?`<small>Motivo: ${esc(i.voidReason)}</small>`:''}</td><td>${date(i.dueOn)}</td><td>${money(i.amountMinor,c)}</td><td>${money(i.remainingMinor,c)}</td><td>${badge(i.status)}</td>${platform?`<td>${i.remainingMinor>0?`<button data-pay="${i.id}">Registrar pago</button>`:''}${i.status!=='VOID'&&i.paidMinor===0?` <button class="quiet" data-void="${i.id}">Anular</button>`:''}</td>`:''}</tr>`))}</section><section class="panel"><h2>Pagos registrados</h2>${table(['Referencia','Fecha','Medio','Importe','Estado',...(platform?['']:[])],d.payments.map(p=>`<tr><td>${esc(p.reference)}<small>Cargo: ${esc(p.invoiceId)}</small></td><td>${date(p.paidOn)}</td><td>${esc(names[p.method])}</td><td>${money(p.amountMinor,c)}</td><td>${p.reversed?'Revertido':'Aplicado'}${p.reversalReason?`<small>${esc(p.reversalReason)}</small>`:''}</td>${platform?`<td>${!p.reversed?`<button class="quiet" data-reverse="${p.id}">Revertir</button>`:''}</td>`:''}</tr>`))}</section><div class="commercial-pager"><button class="quiet" id="accountPrev" ${offset===0?'disabled':''}>Anterior</button><span>Página ${Math.floor(offset/100)+1} · ${d.summary.invoiceCount} cargos / ${d.paymentCount} pagos</span><button class="quiet" id="accountNext" ${Math.max(d.summary.invoiceCount,d.paymentCount)<=offset+100?'disabled':''}>Siguiente</button></div><p class="commercial-note">Los pagos son registros administrativos de cobros recibidos. No se debita una tarjeta ni una cuenta bancaria desde este panel. Los cargos no sustituyen una factura fiscal.</p>`;
        action('accountPrev',async()=>{offset=Math.max(0,offset-100);await loadAccount()});action('accountNext',async()=>{offset+=100;await loadAccount()});
        if(!platform)return;
        action('addCharge',()=>dialog('Añadir cargo',`${field('description','Concepto','text','','required maxlength="200"')}${amount('amount',`Importe (${c})`)}${field('dueOn','Vencimiento','date',d.today,'required')}`,async(v,f)=>{const payload={description:v.description,amountMinor:minor(v.amount),dueOn:v.dueOn};await api(`${endpoint()}/charges`,payload,'POST',operationKey(f,payload));await loadAccount()},'Crear cargo'));
        root.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>{
            const i=d.invoices.find(i=>i.id===b.dataset.pay);
            dialog('Registrar pago recibido',`${amount('amount',`Importe (${c})`,(i.remainingMinor/100).toFixed(2))}${field('reference','Referencia única del comprobante','text','','required maxlength="100"')}${select('method','Medio de pago',Object.entries(names).filter(([v])=>['TRANSFER','CASH','CARD','OTHER'].includes(v)),'TRANSFER')}${field('paidOn','Fecha del pago','date',d.today,`required max="${d.today}"`)}`,async(v,f)=>{const payload={invoiceId:i.id,amountMinor:minor(v.amount),reference:v.reference,method:v.method,paidOn:v.paidOn};await api(`${endpoint()}/payments`,payload,'POST',operationKey(f,payload));await loadAccount()},'Registrar pago',`${i.description}. Pendiente: ${money(i.remainingMinor,c)}. Se permiten pagos parciales.`);
        });
        function correction(path,title,message){dialog(title,field('reason','Motivo','text','','required maxlength="500"'),async(v,f)=>{await api(endpoint()+path,v,'POST',operationKey(f,v));await loadAccount()},'Confirmar',message)}
        root.querySelectorAll('[data-void]').forEach(b=>b.onclick=()=>correction(`/charges/${b.dataset.void}/void`,'Anular cargo','Se conserva el cargo y el motivo en el historial. Solo se pueden anular cargos sin pagos activos.'));
        root.querySelectorAll('[data-reverse]').forEach(b=>b.onclick=()=>correction(`/payments/${b.dataset.reverse}/reverse`,'Revertir registro de pago','El saldo volverá a estar pendiente. Esta corrección no devuelve dinero a una cuenta bancaria.'));
    }
    function renderMembership(root) {
        const d=accountData,p=d.membership?.plan||{name:'',feeMinor:0,startedOn:d.today,nextChargeOn:d.today,intervalMonths:1,dueDays:7,graceDays:7,autoSuspend:false,recurring:true,anchorDay:Number(d.today.slice(-2))};
        const next=d.membership?.nextChargeOn||p.nextChargeOn;
        root.innerHTML=`<div class="commercial-split"><section class="panel"><h2>Membresía del negocio</h2><form id="membershipForm">${field('name','Nombre del plan','text',p.name,'required maxlength="100"')}${amount('fee',`Tarifa (${d.business.currency})`,(p.feeMinor/100).toFixed(2))}${select('intervalMonths','Ciclo',[[1,'Mensual'],[3,'Trimestral'],[6,'Semestral'],[12,'Anual']],p.intervalMonths)}<div class="row"><div>${field('startedOn','Alta de membresía','date',p.startedOn,`required max="${d.today}"`)}</div><div>${field('nextChargeOn','Próximo cargo','date',next,`required min="${d.today}"`)}</div></div><div class="row"><div>${field('anchorDay','Día de corte','number',p.anchorDay,'required min="1" max="31"')}</div><div>${field('dueDays','Días para pagar','number',p.dueDays,'required min="0" max="90"')}</div><div>${field('graceDays','Días de gracia','number',p.graceDays,'required min="0" max="90"')}</div></div><label class="check"><input name="recurring" type="checkbox" ${p.recurring?'checked':''}>Generar cargos recurrentes</label><label class="check"><input name="autoSuspend" type="checkbox" ${p.autoSuspend?'checked':''}>Suspender al superar el plazo de gracia</label><button type="submit">Guardar membresía</button></form></section><section class="panel"><h2>Reglas claras</h2><p>La tarifa nueva se aplica a los cargos futuros. Los cargos ya emitidos conservan su importe y versión.</p><p>El día 31 se ajusta al último día de los meses más cortos y vuelve al 31 cuando corresponde.</p><p>La suspensión automática es opcional. Se activa después del vencimiento más los días de gracia, usando la zona horaria del negocio.</p><p>Pausar los cargos no elimina deudas. Dar de baja el negocio también pausa su membresía; al reactivarlo, debes reanudarla con una fecha de cargo válida.</p><p class="commercial-definition">Vencimiento = fecha del cargo + días para pagar. La suspensión comienza al día siguiente de terminar la gracia.</p></section></div>`;
        form('membershipForm',async v=>{const plan={name:v.name,feeMinor:minor(v.fee),startedOn:v.startedOn,nextChargeOn:v.nextChargeOn,intervalMonths:Number(v.intervalMonths),dueDays:Number(v.dueDays),graceDays:Number(v.graceDays),anchorDay:Number(v.anchorDay),autoSuspend:v.autoSuspend==='on',recurring:v.recurring==='on'};await api(`${endpoint()}/membership`,{expectedVersion:d.membership?.version||0,plan},'PUT');await loadAccount();notice('Membresía guardada. Los cargos anteriores se conservan.')});
    }
    function renderAccess(root) {
        const d=accountData,a=d.access;
        root.innerHTML=`${warnings(d)}<div class="commercial-split"><section class="panel"><h2>Estado del negocio</h2><p>Estado manual: ${badge(a.state)} · Estado actual: ${badge(a.effectiveState)}</p><form id="accessForm">${select('state','Nuevo estado',[['ACTIVE','Activo'],['SUSPENDED','Suspendido'],['CLOSED','Dado de baja']],a.state)}${field('reason','Motivo del cambio','text','','required maxlength="500"')}<button type="submit">Aplicar cambio</button></form></section><section class="panel"><h2>Qué ocurre al suspender</h2><p>Se pausan compras, nuevos canjes, registros y cambios de promociones. Los saldos y el historial permanecen disponibles, y las reservas pueden cancelarse o expirar.</p><p>El dueño conserva el acceso a su cuenta y sus informes. Los demás negocios siguen operando.</p><p>Una suspensión manual requiere reactivación manual. Si se debe a mora automática, pagar todo el saldo fuera de gracia recupera el acceso.</p><p class="commercial-definition">Suspender mantiene los cargos programados. Dar de baja detiene los cargos futuros. Los cargos ya vencidos o emitidos se conservan.</p></section></div><section class="panel"><h2>Historial de estados</h2>${table(['Estado','Motivo','Fecha'],d.accessHistory.map(h=>`<tr><td>${badge(h.state)}</td><td>${esc(h.reason)}</td><td>${date(h.at)}</td></tr>`))}</section><section class="panel"><h2>Actividad administrativa reciente</h2>${table(['Acción','Fecha'],d.history.map(h=>`<tr><td>${esc(({BILLING_PLAN:'Membresía actualizada',BILLING_CHARGE:'Cargo creado',BILLING_PAYMENT:'Pago registrado',BILLING_REVERSAL:'Pago revertido',BILLING_VOID:'Cargo anulado',BUSINESS_ACTIVE:'Negocio activado',BUSINESS_SUSPENDED:'Negocio suspendido',BUSINESS_CLOSED:'Negocio dado de baja',BUSINESS_NOTICE:'Aviso publicado'})[h.action]||'Cambio administrativo')}</td><td>${esc(new Date(h.at).toLocaleString())}</td></tr>`))}</section>`;
        form('accessForm',async v=>{await api(`${endpoint()}/access`,{...v,expectedVersion:a.version},'PUT');await loadAccount();notice('Estado actualizado.')});
    }
    function renderNotices(root) {
        const d=accountData;
        root.innerHTML=`${warnings(d)}${platform?`<section class="panel"><h2>Publicar aviso para el negocio</h2><form id="noticeForm">${field('title','Título','text','','required maxlength="120"')}<label for="body">Mensaje</label><textarea id="body" name="body" rows="4" required maxlength="2000"></textarea><div class="row"><div>${select('severity','Prioridad',[['INFO','Información'],['WARNING','Advertencia'],['URGENT','Urgente']],'INFO')}</div><div>${field('expiresOn','Visible hasta (opcional)','date','',`min="${d.today}"`)}</div></div><button type="submit">Publicar aviso</button></form><p class="commercial-note">Aparecerá dentro del portal del negocio. No se envía por correo ni WhatsApp.</p></section>`:''}<section class="panel"><h2>Avisos vigentes</h2>${d.notices.map(n=>`<article class="commercial-notice">${badge(n.severity)}<h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><p class="small">${date(n.createdAt)}</p>${!platform?`<button class="quiet" data-read="${n.id}" ${n.read?'disabled':''}>${n.read?'Leído':'Marcar como leído'}</button>`:''}</article>`).join('')||'<p>No tienes avisos pendientes.</p>'}</section>`;
        if(platform)form('noticeForm',async(v,f)=>{const payload={...v,expiresOn:v.expiresOn||null};await api(`${endpoint()}/notices`,payload,'POST',operationKey(f,payload));await loadAccount();notice('Aviso publicado en el portal.')});
        root.querySelectorAll('[data-read]').forEach(b=>b.onclick=handle(async()=>{await api(`/api/staff/notices/${b.dataset.read}/read`,{});await loadAccount()}));
    }
    let reportRequest=0, reportResize=null;
    async function renderMetrics(root,days=30) {
        reportResize?.disconnect();
        const ticket=++reportRequest, session=state.token, tab=state.tab, tenant=selected, reportPath=endpoint(), business=accountData.business;
        const valid=()=>root.isConnected&&state.tab===tab&&pane==='metrics'&&ticket===reportRequest&&session===state.token&&(!platform||tenant===selected);
        root.innerHTML='<section class="panel" role="status">Preparando tus informes…</section>';
        let data;
        try{data=await api(`${reportPath}/metrics?days=${days}`);}catch(issue){if(valid()){root.innerHTML=`<section class="panel"><h2>No pudimos cargar el informe</h2><p role="alert">${esc(issue.message)}</p><button type="button" id="retryReport">Reintentar</button></section>`;root.querySelector('#retryReport').onclick=()=>renderMetrics(root,days);}return;}
        if(!valid())return;
        const c=business.currency, formatMoney=value=>new Intl.NumberFormat('es-EC',{style:'currency',currency:c,currencyDisplay:'narrowSymbol'}).format(Number(value||0)/100), n=value=>Number(value||0), percentage=(current,previous)=>previous>0?`${((current-previous)*100/previous).toFixed(1)}% frente al período anterior`:'Sin base anterior para comparar';
        const series=[], from=data.fromDate||data.from.slice(0,10), byDate=new Map(data.daily.map(x=>[x.day,x]));
        for(let i=0;i<days;i++){const day=new Date(Date.parse(from+'T00:00:00Z')+i*86400000).toISOString().slice(0,10);series.push({day,purchases:0,clients:0,salesMinor:0,...byDate.get(day)});}
        const bars=(rows,value,format)=>{const largest=Math.max(1,...rows.map(value));return rows.map(x=>`<div class="report-bar"><div><strong>${esc(x.name)}</strong><span>${esc(format(value(x)))}</span></div><div class="report-bar-track"><span style="width:${Math.min(100,Math.max(0,value(x)/largest*100))}%"></span></div></div>`).join('')||'<p class="report-empty">Todavía no hay datos para este gráfico.</p>';};
        const repeat=Math.max(0,Math.min(100,n(data.repeatRate))), firstOnly=Math.max(0,n(data.activeClients)-n(data.repeatClients));
        root.innerHTML=`<section class="panel report-header"><div class="commercial-heading-row"><div><span class="eyebrow">${esc(business.name)} · Informes</span><h2>Entiende cada regreso.</h2><p>${date(from)} — ${date(data.throughDate||data.through)} · ${esc(business.timezone)} · ${esc(c)}</p></div><div>${select('reportDays','Período',[[7,'Últimos 7 días'],[30,'Últimos 30 días'],[90,'Últimos 90 días'],[365,'Últimos 365 días']],days)}<button type="button" class="quiet" id="exportReport">Descargar datos diarios CSV</button></div></div><p class="small">El período actual incluye hoy hasta el momento de consulta. La comparación usa los ${days} días completos anteriores (${date(data.previousFromDate)} — ${date(data.previousThroughDate)}).</p><div class="commercial-stats report-kpis">${stat('Total pagado',formatMoney(data.salesMinor),percentage(n(data.salesMinor),n(data.previousSalesMinor)))}${stat('Compras registradas',data.purchases,percentage(n(data.purchases),n(data.previousPurchases)))}${stat('Compra media',data.purchases?formatMoney(data.salesMinor/data.purchases):'—','Total pagado ÷ compras registradas')}${stat('Premios reclamados',data.redemptions,'Canjes confirmados durante el período')}</div></section>
            <section class="panel report-trend"><div class="commercial-heading-row"><div><h3>Cómo evoluciona la actividad</h3><p>Incluye los días sin compras con valor cero.</p></div>${select('reportMetric','Ver en el gráfico',[['salesMinor','Total pagado'],['purchases','Compras'],['clients','Clientes que compraron']],'salesMinor')}</div><div id="reportChart" class="report-chart"></div><label for="reportDay">Explorar un día</label><input type="range" id="reportDay" min="0" max="${days-1}" value="${days-1}" step="1"><p id="reportDayDetail" class="report-day-detail" aria-live="polite"></p></section>
            <div class="report-columns"><section class="panel"><h3>Clientes que vuelven</h3><div class="report-repeat"><svg viewBox="0 0 160 160" role="img" aria-label="${repeat.toFixed(1)} por ciento de compradores con dos o más compras"><circle cx="80" cy="80" r="60" fill="none" stroke="#e4eaf2" stroke-width="17"/><circle cx="80" cy="80" r="60" fill="none" stroke="#0b1f3a" stroke-width="17" pathLength="100" stroke-dasharray="${repeat} 100" transform="rotate(-90 80 80)"/><text x="80" y="85" text-anchor="middle">${repeat.toFixed(1)}%</text></svg><div><p><strong>${esc(data.repeatClients)}</strong> con dos o más compras</p><p><strong>${firstOnly}</strong> con una compra</p><p class="small">Entre ${esc(data.activeClients)} compradores distintos del período. Es repetición de compra, no una tasa de retención.</p></div></div></section><section class="panel"><h3>Crecimiento de la comunidad</h3>${bars([{name:'Altas del período anterior',value:n(data.previousNewClients)},{name:'Altas del período actual',value:n(data.newClients)}],x=>x.value,String)}<p>${esc(percentage(n(data.newClients),n(data.previousNewClients)))}</p><p class="small">${esc(data.totalClients)} clientes registrados en total histórico. Las altas no equivalen a compradores.</p></section></div>
            <section class="panel"><h3>Ventas por sucursal</h3>${bars(data.branches||[],x=>n(x.salesMinor),formatMoney)}<details><summary>Ver cifras por sucursal</summary>${table(['Sucursal','Compras','Compradores','Total pagado','Premios'],(data.branches||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${x.purchases}</td><td>${x.clients}</td><td>${formatMoney(x.salesMinor)}</td><td>${x.redemptions}</td></tr>`))}</details><p class="small">Hasta 50 sucursales, ordenadas por total pagado. Un cliente puede comprar en varias; no se suman sus conteos para calcular clientes únicos.</p></section>
            <div class="report-columns"><section class="panel"><h3>Qué categorías se compran más</h3>${bars(data.categories||[],x=>n(x.units),v=>v+' unidades')}<p class="small">Hasta ocho categorías. Solo compras con productos detallados; las compras registradas únicamente por total no se pueden clasificar.</p></section><section class="panel"><h3>Premios más reclamados</h3>${bars(data.topRewards||[],x=>n(x.claims),v=>v+' canjes')}<p class="small">Hasta ocho premios, con entregas confirmadas. El historial conserva los premios de promociones retiradas.</p></section></div>
            <details class="panel report-table"><summary>Consultar los datos diarios</summary>${table(['Día','Compras','Compradores','Total pagado'],series.map(x=>`<tr><td>${date(x.day)}</td><td>${x.purchases}</td><td>${x.clients}</td><td>${formatMoney(x.salesMinor)}</td></tr>`))}<p class="small">Los compradores diarios no se suman para calcular clientes únicos del período.</p></details><p class="commercial-definition">Estos informes consultan las operaciones registradas en Loyalty. No incluyen ventas fuera del sistema, no modifican saldos y no calculan utilidades ni atribuyen ventas a una campaña.</p>`;
        const plot=()=>{
            const metric=root.querySelector('#reportMetric').value,index=Number(root.querySelector('#reportDay').value),values=series.map(x=>n(x[metric])),maximum=Math.max(1,...values),width=Math.max(280,Math.floor(root.querySelector('#reportChart').clientWidth)),right=width-20,x=i=>24+(series.length===1?(right-24)/2:i/(series.length-1)*(right-24)),y=v=>205-v/maximum*170;
            const format=metric==='salesMinor'?formatMoney:v=>new Intl.NumberFormat('es-EC').format(v);
            const points=values.map((v,i)=>`${x(i).toFixed(2)},${y(v).toFixed(2)}`).join(' '),ticks=[...new Set([0,metric==='salesMinor'?maximum/2:Math.floor(maximum/2),maximum])];
            root.querySelector('#reportChart').innerHTML=`<svg viewBox="0 0 ${width} 245" role="img" aria-label="${esc(root.querySelector('#reportMetric').selectedOptions[0].textContent)} por día"><title>${esc('Actividad del '+from+' al '+series.at(-1).day)}</title><polygon points="24,205 ${points} ${right},205" fill="#e6effa"/>${ticks.map(v=>`<line x1="24" y1="${y(v)}" x2="${right}" y2="${y(v)}" stroke="#d7e1ee"/><text x="24" y="${y(v)-7}" class="chart-axis">${esc(format(v))}</text>`).join('')}<polyline points="${points}" fill="none" stroke="#0b1f3a" stroke-width="3" stroke-linejoin="round"/><line x1="${x(index)}" x2="${x(index)}" y1="30" y2="205" stroke="#64748b" stroke-dasharray="4 4"/><circle cx="${x(index)}" cy="${y(values[index])}" r="5" fill="#315da8" stroke="white" stroke-width="2"/><text x="24" y="233" class="chart-axis">${esc(series[0].day)}</text><text x="${right}" y="233" text-anchor="end" class="chart-axis">${esc(series.at(-1).day)}</text></svg>`;
            const row=series[index];root.querySelector('#reportDayDetail').textContent=`${row.day} · ${row.purchases} compras · ${row.clients} compradores · ${formatMoney(row.salesMinor)}`;
        };
        root.querySelector('#reportMetric').onchange=plot;root.querySelector('#reportDay').oninput=plot;plot();
        const observer=new ResizeObserver(()=>{if(valid())plot();else observer.disconnect();});reportResize=observer;observer.observe(root.querySelector('#reportChart'));
        root.querySelector('#reportDays').onchange=e=>renderMetrics(root,Number(e.target.value));
        root.querySelector('#exportReport').onclick=()=>{
            const text='\uFEFFDía,Compras,Compradores,Total pagado,Moneda\r\n'+series.map(x=>[x.day,x.purchases,x.clients,(x.salesMinor/100).toFixed(2),c].join(',')).join('\r\n');
            const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`loyalty-informe-${from}-${series.at(-1).day}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
        };
    }
    const baseMerchant=renderMerchant;
    renderMerchant=function(){
        ++requestVersion;
        baseMerchant();const nav=app.querySelector('nav');
        if(state.data.role==='OWNER'){
            for(const [tab,label] of [['business','Mi negocio'],['account','Mi cuenta'],['reports','Informes']]){
                const b=document.createElement('button');b.textContent=label;b.dataset.tab=tab;b.classList.toggle('active',state.tab===tab);
                b.onclick=()=>{state.tab=tab;renderMerchant()};nav.append(b);
            }
            if(state.tab==='business'){renderBusinessProfile(document.querySelector('#content')).catch(e=>notice(e.message));return;}
            if(['account','reports'].includes(state.tab)){pane=state.tab==='reports'?'metrics':'account';offset=0;document.querySelector('#content').innerHTML='<p role="status">Cargando cuenta…</p>';loadAccount().catch(e=>notice(e.message));return;}
        }
        const content=document.querySelector('#content');
        api('/api/staff/access').then(a=>{if(!content.isConnected||a.canOperate)return;const n=document.createElement('div');n.className='commercial-alert';n.textContent='Las nuevas operaciones están pausadas. Los datos y saldos se conservan. El dueño puede consultar Mi cuenta.';content.prepend(n);content.querySelectorAll('form button').forEach(b=>b.disabled=true)}).catch(e=>notice(e.message));
    };;
    const baseCustomer=customerCard;
    customerCard=async function(){await baseCustomer();const a=await api('/api/me/access');if(!a.canOperate&&state.token){const n=document.createElement('div');n.className='commercial-alert';n.textContent='Este negocio tiene pausadas las nuevas operaciones. Tu saldo e historial se conservan.';app.prepend(n);app.querySelectorAll('[data-reserve]').forEach(b=>b.disabled=true)}};
    const baseExit=exit.onclick;exit.onclick=async()=>{++requestVersion;document.querySelector('#commercialDialog')?.remove();selected=null;accountData=null;if(platform){state.token='';login()}else await baseExit()};
    if(platform)login();
})();
